import * as vercelBlob from '@vercel/blob';
import { NextResponse } from 'next/server';

export async function POST(request: Request): Promise<NextResponse> {
  const body: { urls: string[] } = await request.json();

  if (body.urls.length > 0) {
    await vercelBlob.del(body.urls);
  }

  return NextResponse.json({ deleted: true });
}

import * as vercelBlob from '@vercel/blob';
import { NextResponse } from 'next/server';

export async function DELETE(request: Request): Promise<NextResponse> {
  const { searchParams } = new URL(request.url);
  const prefix = searchParams.get('prefix') ?? '';
  let hasMore = true;
  let cursor: string | undefined;
  while (hasMore) {
    const listResult = await vercelBlob.list({
      cursor,
      prefix,
    });
    if (listResult.blobs.length > 0) {
      await vercelBlob.del(listResult.blobs.map((blob) => blob.url));
    }
    hasMore = listResult.hasMore;
    cursor = listResult.cursor;
  }

  return NextResponse.json({ success: true });
}

import * as vercelBlob from '@vercel/blob';
import { NextResponse } from 'next/server';
import { validateUploadToken } from '../../../validate-upload-token';

export async function POST(request: Request): Promise<NextResponse> {
  const { searchParams } = new URL(request.url);
  const pathname = searchParams.get('filename');

  if (pathname === null) {
    return NextResponse.json({ message: 'Missing filename' }, { status: 400 });
  }

  if (!validateUploadToken(request)) {
    return NextResponse.json({ message: 'Not authorized' }, { status: 401 });
  }

  // Multipart upload with an empty ReadableStream — this used to deadlock
  // because uploadAllParts never called resolve() when the stream was empty.
  const emptyStream = new ReadableStream({
    start(controller) {
      controller.close();
    },
  });

  try {
    const blob = await vercelBlob.put(pathname, emptyStream, {
      access: 'public',
      multipart: true,
      addRandomSuffix: true,
    });

    return NextResponse.json(blob);
  } catch (error) {
    // The server rejects empty multipart uploads ("Invalid body") which is
    // expected. The important thing is that put() resolved instead of hanging.
    return NextResponse.json(
      { resolved: true, error: (error as Error).message },
      { status: 400 },
    );
  }
}

import * as vercelBlob from '@vercel/blob';
import { NextResponse } from 'next/server';

export async function GET(request: Request): Promise<NextResponse> {
  const { searchParams } = new URL(request.url);
  const cursor = searchParams.get('cursor') ?? undefined;
  const limit = parseInt(searchParams.get('limit') ?? '', 10);
  const prefix = searchParams.get('prefix') ?? '';

  const data = await vercelBlob.list({
    cursor,
    limit,
    prefix,
  });

  return NextResponse.json(data);
}

import { issueSignedToken, presignUrl } from '@vercel/blob';
import { NextResponse } from 'next/server';

function parseBlobObjectUrl(
  blobUrl: string,
): { access: 'public' | 'private'; pathname: string } | null {
  let u: URL;
  try {
    u = new URL(blobUrl);
  } catch {
    return null;
  }
  const { hostname } = u;
  if (hostname.endsWith('.public.blob.vercel-storage.com')) {
    return { access: 'public', pathname: pathnameFromObjectUrl(u.pathname) };
  }
  if (hostname.endsWith('.private.blob.vercel-storage.com')) {
    return { access: 'private', pathname: pathnameFromObjectUrl(u.pathname) };
  }
  return null;
}

function pathnameFromObjectUrl(urlPathname: string): string {
  const trimmed = urlPathname.startsWith('/')
    ? urlPathname.slice(1)
    : urlPathname;
  return trimmed
    .split('/')
    .map((segment) => decodeURIComponent(segment))
    .join('/');
}

export async function POST(request: Request): Promise<NextResponse> {
  const body = (await request.json()) as { url?: string };
  if (!body.url || typeof body.url !== 'string') {
    return NextResponse.json({ error: 'url is required' }, { status: 400 });
  }

  const parsed = parseBlobObjectUrl(body.url);
  if (!parsed) {
    return NextResponse.json(
      {
        error:
          'url must be a Vercel Blob object URL (*.public|*.private.blob.vercel-storage.com)',
      },
      { status: 400 },
    );
  }

  try {
    const token = await issueSignedToken({
      pathname: parsed.pathname,
      operations: ['head'],
      validUntil: Date.now() + 60 * 60 * 1000, // 1 hour
    });
    const { presignedUrl } = await presignUrl(token, {
      operation: 'head',
      pathname: parsed.pathname,
      access: parsed.access,
      validUntil: Date.now() + 30 * 60 * 1000, // 30 minutes
    });
    return NextResponse.json({ presignedUrl });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return NextResponse.json({ error: message }, { status: 400 });
  }
}

